import sys
import json
import os
from decimal import Decimal


def extract_fact(award, rule_id, fact_name):
    if rule_id == "usa.period_3y":
        pop = award.get("period_of_performance") or {}
        if fact_name == "performance start":
            val = pop.get("start_date")
            if val is not None:
                val_str = str(val).split("T")[0].split()[0]
                if val_str:
                    return val_str, val_str
            return None
        elif fact_name == "performance end":
            val = pop.get("end_date")
            if val is not None:
                val_str = str(val).split("T")[0].split()[0]
                if val_str:
                    return val_str, val_str
            return None
    elif rule_id == "usa.obligated_95":
        if fact_name == "amount obligated":
            val = award.get("total_obligation")
            if val is not None:
                d = Decimal(str(val))
                return str(val), d
            return None
        elif fact_name == "potential value":
            val = award.get("base_and_all_options")
            if val is not None:
                d = Decimal(str(val))
                return str(val), d
            return None
    return None


def main():
    if len(sys.argv) < 3:
        sys.exit(1)

    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    with open(manifest_path, "r", encoding="utf-8") as f:
        manifest = json.load(f)

    awards_path = os.path.join(packet_dir, "usaspending_awards.json")
    awards = []
    if os.path.exists(awards_path):
        with open(awards_path, "r", encoding="utf-8") as f:
            awards = json.load(f, parse_float=Decimal, parse_int=Decimal)

    awards_by_id = {}
    for award in awards:
        uid = award.get("generated_unique_award_id")
        if uid:
            awards_by_id.setdefault(uid, []).append(award)

    result = {}
    pairs = manifest.get("pairs", [])
    facts_by_rule = manifest.get("facts", {})

    for pair in pairs:
        rule_id, entity = pair.split("::", 1)
        facts = facts_by_rule.get(rule_id, [])
        pair_result = {}

        matching_awards = awards_by_id.get(entity, [])

        for fact_name in facts:
            extracted_values = []
            for award in matching_awards:
                extracted = extract_fact(award, rule_id, fact_name)
                if extracted is not None:
                    extracted_values.append(extracted)

            if not extracted_values:
                pair_result[fact_name] = "ABSENT"
            else:
                first_disp, first_norm = extracted_values[0]
                conflict = any(norm != first_norm for _, norm in extracted_values[1:])
                if conflict:
                    pair_result[fact_name] = "CONFLICT"
                else:
                    pair_result[fact_name] = [first_disp, "usaspending_awards"]

        result[pair] = pair_result

    print(json.dumps(result, indent=2))


if __name__ == "__main__":
    main()
