import json
import os
import re
import sys
from decimal import Decimal


def format_decimal(d):
    if not isinstance(d, Decimal):
        d = Decimal(str(d))
    s = str(d)
    if 'e' in s or 'E' in s:
        return format(d, 'f')
    return s


def format_date(raw):
    s = str(raw).strip()
    match = re.search(r'\b(\d{4}-\d{2}-\d{2})\b', s)
    if match:
        return match.group(1)
    return s


def extract_fact_raw(record, fact_name):
    if fact_name == "performance start":
        pop = record.get("period_of_performance")
        val = pop.get("start_date") if isinstance(pop, dict) else None
        return ("date", val)
    elif fact_name == "performance end":
        pop = record.get("period_of_performance")
        val = pop.get("end_date") if isinstance(pop, dict) else None
        return ("date", val)
    elif fact_name == "amount obligated":
        return ("amount", record.get("total_obligation"))
    elif fact_name == "potential value":
        return ("base_and_all_options", record.get("base_and_all_options"))
    return (None, None)


def main():
    if len(sys.argv) < 3:
