import sys
import json
from pathlib import Path
from decimal import Decimal


FACT_DEFINITIONS = {
    "performance start": {
        "doc": "usaspending_awards",
        "path": "period_of_performance.start_date",
        "type": "date",
    },
    "performance end": {
        "doc": "usaspending_awards",
        "path": "period_of_performance.end_date",
        "type": "date",
    },
    "amount obligated": {
        "doc": "usaspending_awards",
        "path": "total_obligation",
        "type": "amount",
    },
    "potential value": {
        "doc": "usaspending_awards",
        "path": "base_and_all_options",
        "type": "amount",
    },
}


def get_nested_field(record, path):
    parts = path.split(".")
    curr = record
    for part in parts:
        if isinstance(curr, dict):
            curr = curr.get(part)
        else:
            return None
    return curr


def load_awards(packet_dir):
    award_file = packet_dir / "usaspending_awards.json"
    if not award_file.exists():
        for f in packet_dir.iterdir():
            if f.name.lower() == "usaspending_awards.json":
                award_file = f
                break
    if not award_file.exists():
        return []

    with open(award_file, "r", encoding="utf-8") as f:
        return json.load(f)


def main():
    if len(sys.argv) < 3:
        sys.exit(1)

    packet_dir = Path(sys.argv[1])
    manifest_file = Path(sys.argv[2])

    with open(manifest_file, "r", encoding="utf-8") as f:
        manifest = json.load(f)

    awards = load_awards(packet_dir)

    # Index awards by generated_unique_award_id and id
    awards_by_id = {}
    for award in awards:
        gen_id = award.get("generated_unique_award_id")
        if gen_id:
            awards_by_id.setdefault(gen_id, []).append(award)
        raw_id = award.get("id")
        if raw_id is not None:
            awards_by_id.setdefault(str(raw_id), []).append(award)

    results = {}
    pairs = manifest.get("pairs", [])
    facts_map = manifest.get("facts", {})

    for pair in pairs:
        if "::" in pair:
            rule_id, entity = pair.split("::", 1)
        else:
            rule_id, entity = pair, ""

        rule_facts = facts_map.get(rule_id, [])
        pair_result = {}

        matching_records = awards_by_id.get(entity, [])

        for fact_name in rule_facts:
            fact_def = FACT_DEFINITIONS.get(fact_name)
            if not fact_def:
                pair_result[fact_name] = "ABSENT"
                continue

            doc_name = fact_def["doc"]
            field_path = fact_def["path"]
            field_type = fact_def["type"]

            raw_values = []
            for rec in matching_records:
                val = get_nested_field(rec, field_path)
                if val is not None:
                    raw_values.append(val)

            if not raw_values:
                pair_result[fact_name] = "ABSENT"
                continue

            if field_type == "amount":
                # Validate and normalize decimal amounts
                normalized = []
                conflict = False
                for v in raw_values:
                    try:
                        d = Decimal(str(v))
                        normalized.append(d)
                    except Exception:
                        conflict = True
                        break

                if conflict or not normalized:
                    pair_result[fact_name] = "CONFLICT"
                elif all(d == normalized[0] for d in normalized):
                    pair_result[fact_name] = [str(raw_values[0]), doc_name]
                else:
                    pair_result[fact_name] = "CONFLICT"

            elif field_type == "date":
                # Normalize dates to YYYY-MM-DD
                formatted_dates = [str(v).strip()[:10] for v in raw_values]
                if all(d == formatted_dates[0] for d in formatted_dates):
                    pair_result[fact_name] = [formatted_dates[0], doc_name]
                else:
                    pair_result[fact_name] = "CONFLICT"

            else:
                str_values = [str(v).strip() for v in raw_values]
                if all(v == str_values[0] for v in str_values):
                    pair_result[fact_name] = [str_values[0], doc_name]
                else:
                    pair_result[fact_name] = "CONFLICT"

        results[pair] = pair_result

    print(json.dumps(results, indent=2))


if __name__ == "__main__":
    main()
