import sys
import json
import os
from decimal import Decimal

def clean_amount(val):
    if val is None:
        return None
    s = str(val).strip().replace('$', '').replace(',', '')
    if not s or s.lower() in ('null', 'none'):
        return None
    return s

def clean_date(val):
    if val is None:
        return None
    s = str(val).strip()
    if not s or s.lower() in ('null', 'none'):
        return None
    if len(s) >= 10 and s[4] == '-' and s[7] == '-':
        return s[:10]
    return s

def are_amounts_equal(a, b):
    try:
        return Decimal(a) == Decimal(b)
    except Exception:
        return a == b

def extract_fact_value(award, fact_name):
    doc = "usaspending_awards"
    if fact_name == "performance start":
        pop = award.get("period_of_performance")
        val = clean_date(pop.get("start_date")) if isinstance(pop, dict) else None
        return val, doc, False
    elif fact_name == "performance end":
        pop = award.get("period_of_performance")
        val = clean_date(pop.get("end_date")) if isinstance(pop, dict) else None
        return val, doc, False
    elif fact_name == "amount obligated":
        val = clean_amount(award.get("total_obligation"))
        return val, doc, True
    elif fact_name == "potential value":
        val = clean_amount(award.get("base_and_all_options"))
        return val, doc, True
    return None, doc, False

def main():
    if len(sys.argv) < 3:
        sys.exit(1)

    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    with open(manifest_path, "r", encoding="utf-8") as f:
        manifest = json.load(f)

    awards_file = os.path.join(packet_dir, "usaspending_awards.json")
    awards = []
    if os.path.exists(awards_file):
        with open(awards_file, "r", encoding="utf-8") as f:
            awards = json.load(f, parse_float=Decimal, parse_int=Decimal)

    awards_by_id = {}
    for award in awards:
        uid = award.get("generated_unique_award_id")
        if uid:
            awards_by_id.setdefault(str(uid), []).append(award)

    result = {}
    pairs = manifest.get("pairs", [])
    facts_spec = manifest.get("facts", {})

    for pair in pairs:
        if "::" in pair:
            rule_id, entity = pair.split("::", 1)
        else:
            rule_id, entity = pair, ""

        facts = facts_spec.get(rule_id, [])
        entity_awards = awards_by_id.get(entity, [])
        pair_res = {}

        for fact in facts:
            if not entity_awards:
                pair_res[fact] = "ABSENT"
                continue

            values = []
            doc_name = "usaspending_awards"
            is_amount = False

            for award in entity_awards:
                val, doc, is_amt = extract_fact_value(award, fact)
                doc_name = doc
                is_amount = is_amt
                if val is not None:
                    values.append(val)

            if not values:
                pair_res[fact] = "ABSENT"
            else:
                if is_amount:
                    distinct = []
                    for v in values:
                        if not any(are_amounts_equal(v, d) for d in distinct):
                            distinct.append(v)
                    if len(distinct) == 1:
                        pair_res[fact] = [str(distinct[0]), doc_name]
                    else:
                        pair_res[fact] = "CONFLICT"
                else:
                    unique_vals = list(set(values))
                    if len(unique_vals) == 1:
                        pair_res[fact] = [unique_vals[0], doc_name]
                    else:
                        pair_res[fact] = "CONFLICT"

        result[pair] = pair_res

    print(json.dumps(result, indent=1))

if __name__ == "__main__":
    main()
